mapper.select:
SELECT t.TRADE_ID tradeId,/**交易编号**/ null outTradeId, /*外部成交编号*/ deal.BOOKSET_ID prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ fpt.TYPE_6 contractType, /**合约类型**/ ftr.finprod_id targetId, /**合约标的**/ t.PS ps,/**交易方向**/ t.TRADE_DATE tradeDate,/**交易日**/ ftr.TERM term,/**期限**/ t.VDATE vdate,/**起息日**/ t.MDATE mdate,/**到期日**/ t.COUNTER_ID counterId,/**交易对手**/ ftr.PRIN nomCapi,/**名义本金**/ null optFee,/**期权费**/ t.CCY ccy,/**币种**/ stl.SETTLE_AMT settleAmt,/**结算金额**/ stl.MY_ACCT_NO acctNo/**资金账户**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_TRADE_PRODUCT ftr on ftr.finprod_id = t.finprod_id LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = ftr.FINPROD_ID LEFT JOIN BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal.BOOKSET_ID LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE =#{busiType} AND stl.ORDER_TYPE in('2749','2748') where t.BUSI_TYPE =#{busiType}
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and deal.BOOKSET_ID IN
#{finprodId}
and ftr.finprod_id IN
#{targetId}
AND fpt.TYPE_6 IN
#{contractType}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
order by t.TRADE_ID desc

mapper.delete:
DELETE FROM BOK_DETAIL_ID
WHERE BOOKSET_ID = #{booksetId}
  and TRADE_ID = #{tradeId}
